package group16.webapp.common.exception;

import org.springframework.http.HttpStatus;

/**
 * Central catalogue of request-level business/technical errors. Frontend can rely on the enum name.
 * Names follow the design document's REST contract (INVALID_INPUT, UNAUTHENTICATED, STALE_VERSION, ...).
 * Per-session scheduling violations are NOT error codes: they are {@link ConflictCode} values inside
 * the {@code conflicts[]} payload of {@link #CONSTRAINT_VIOLATION}.
 * All codes needed by the MVP modules are declared here up front, so modules do not edit this file.
 */
public enum ErrorCode {
    // ---- Generic ----
    INVALID_INPUT(HttpStatus.BAD_REQUEST, "Invalid input"),
    RESOURCE_NOT_FOUND(HttpStatus.NOT_FOUND, "Resource not found"),
    METHOD_NOT_ALLOWED(HttpStatus.METHOD_NOT_ALLOWED, "HTTP method not supported for this resource"),
    UNSUPPORTED_MEDIA_TYPE(HttpStatus.UNSUPPORTED_MEDIA_TYPE, "Unsupported content type"),
    STALE_VERSION(HttpStatus.CONFLICT, "Data was changed by another request. Please reload and try again"),
    DATA_CONFLICT(HttpStatus.CONFLICT, "Request conflicts with existing data"),
    INTERNAL_ERROR(HttpStatus.INTERNAL_SERVER_ERROR, "Internal server error"),
    /** Contract stubs only (team decision CG-05); must be gone before the backend freeze. */
    NOT_IMPLEMENTED(HttpStatus.NOT_IMPLEMENTED, "Not implemented yet"),

    // ---- Auth ----
    UNAUTHENTICATED(HttpStatus.UNAUTHORIZED, "Authentication required"),
    INVALID_CREDENTIALS(HttpStatus.UNAUTHORIZED, "Invalid email or password"),
    FORBIDDEN(HttpStatus.FORBIDDEN, "You do not have permission to perform this action"),

    // ---- User ----
    EMAIL_ALREADY_EXISTS(HttpStatus.CONFLICT, "Email already in use"),

    // ---- Time / Availability ----
    INVALID_TIME_RANGE(HttpStatus.BAD_REQUEST, "Invalid time range"),
    NO_AVAILABILITY_RULE(HttpStatus.BAD_REQUEST, "No availability rule is set. Please set your available time first"),

    // ---- Scheduling ----
    /** data = ConflictErrorResponse { conflicts: [ { sessionId, code: ConflictCode, message } ] }. */
    CONSTRAINT_VIOLATION(HttpStatus.CONFLICT, "The schedule violates one or more constraints"),

    // ---- Assignment ----
    /** BR-04: a task may have at most one PENDING/ACCEPTED assignment (team addition, not in the design doc). */
    ASSIGNMENT_ALREADY_ACTIVE(HttpStatus.CONFLICT, "This task already has an active assignment"),

    // ---- AI ----
    AI_UNAVAILABLE(HttpStatus.SERVICE_UNAVAILABLE, "AI service is unavailable. Please enter the task manually");

    private final HttpStatus status;
    private final String message;

    ErrorCode(HttpStatus status, String message) {
        this.status = status;
        this.message = message;
    }

    public HttpStatus getStatus() { return status; }
    public String getMessage() { return message; }
}
